#include <stdio.h>

int main() {
    int a = 10;
    char c = 'A';

    int *pi = &a;
    char *pc = &c;

    printf("Size of int*:  %zu\n", sizeof(pi));
    printf("Size of char*: %zu\n", sizeof(pc));

    printf("Read int*:  %d\n", *pi);
    printf("Read char*: %c\n", *pc);
    return 0;
}
